const save=()=>{book.current=record.caseId;book[record.caseId]=record;try{localStorage.setItem('tp-bapa-voyage-v1',JSON.stringify(book))}catch{};if(modal.open&&phase==='negotiation')prepareReports()};
function person(name,color,female=false){return `<g class="bapa-mini-person"><ellipse cy="35" rx="13" ry="5" fill="#36585a35"/><g class="bapa-leg-left"><path d="M-6 21v12" stroke="#53645d" stroke-width="7" stroke-linecap="round"/></g><g class="bapa-leg-right"><path d="M6 21v12" stroke="#53645d" stroke-width="7" stroke-linecap="round"/></g><path d="M-12 3q12-8 24 0l-2 22h-20Z" fill="${color}"/><path d="M-13 6l-5 13M13 6l5 13" stroke="${color}" stroke-width="6" stroke-linecap="round"/><path d="M-14-10q-3-21 14-21q20 0 16 23${female?'l-1 14h-7v-9h-16v10h-8Z':'Z'}" fill="${female?'#70543f':'#5b584b'}"/><ellipse cy="-11" rx="13" ry="15" fill="#f0cfac"/><path d="M-14-17q4-19 25-6l4 8-14-9-10 9Z" fill="${female?'#70543f':'#5b584b'}"/><circle cx="-5" cy="-12" r="1.5" fill="#40584e"/><circle cx="5" cy="-12" r="1.5" fill="#40584e"/><path d="M-3-5q3 3 6 0" fill="none" stroke="#ab8269" stroke-width="1.5"/><text y="56" text-anchor="middle" font-size="13" fill="#24494b" stroke="#fff7e6" stroke-width="3" paint-order="stroke">${esc(name)}</text></g>`}
function flag(country,x,y){let body='';if(country==='TW'){body='<rect width="56" height="36" fill="#df3c39"/><rect width="28" height="20" fill="#294f91"/>';for(let j=0;j<12;j++)body+=`<path d="M14 1l2 8h-4Z" fill="white" transform="rotate(${j*30} 14 10)"/>`;body+='<circle cx="14" cy="10" r="4.5" fill="white"/>'}else if(country==='JP')body='<rect width="56" height="36" fill="#fffef8"/><circle cx="28" cy="18" r="10" fill="#cb4c4b"/>';else if(country==='NL')body='<rect width="56" height="12" fill="#af4c4c"/><rect y="12" width="56" height="12" fill="#fffef4"/><rect y="24" width="56" height="12" fill="#426492"/>';else body='<rect width="19" height="36" fill="#398567"/><rect x="19" width="18" height="36" fill="#fffef4"/><rect x="37" width="19" height="36" fill="#c95854"/>';return `<g transform="translate(${x} ${y})"><path d="M0 0v100" stroke="#e7d4ab" stroke-width="4"/><g transform="translate(2 0)">${body}</g></g>`}
function svg(){return `<svg viewBox="0 0 1200 620" role="img" aria-label="小羊協商號登船航向部本部島，四國旗與圓桌就座動畫"><defs><linearGradient id="sea" x2="0" y2="1"><stop stop-color="#acd4d8"/><stop offset="1" stop-color="#527f95"/></linearGradient></defs><rect width="1200" height="620" fill="url(#sea)"/><g fill="#f9f6e1" class="bapa-cloud"><ellipse cx="180" cy="105" rx="100" ry="20"/><ellipse cx="235" cy="90" rx="80" ry="28"/><ellipse cx="1000" cy="90" rx="140" ry="20"/></g><g stroke="#dbf1e9" opacity=".45" fill="none">${Array.from({length:24},(_,j)=>`<path d="M${j%6*240-60} ${245+Math.floor(j/6)*95}q25 8 50 0"/>`).join('')}</g><g id="bapa-old-port"><path d="M80 330L390 260 625 385 297 510 70 425Z" fill="#a6a18a"/><path d="M80 305L390 235 625 360 297 475 70 400Z" fill="#e1d6b9"/><path d="M110 305l260-60 210 120-270 80Z" fill="#bdd0ad"/><path d="M180 260v-115l210 26v119Z" fill="#aec1b0"/><path d="M390 171l75-38v115l-75 42Z" fill="#819b8c"/><path d="M160 144l78-43 242 31-90 45Z" fill="#7f9783"/><g fill="#fff3bc">${[0,1,2,3].map(i=>`<path d="M${205+i*45} 195v40l23 3v-40Z"/>`).join('')}</g><text x="300" y="280" text-anchor="middle" font-size="22" fill="#345754">國稅查核島</text><path d="M405 385l150 25 115-50-155-22Z" fill="#b69a70"/><path d="M405 393l150 26 115-50" fill="none" stroke="#806f56" stroke-width="8"/></g><g id="bapa-ministry" opacity="0"><path d="M470 360L850 220 1170 360 880 555 490 465Z" fill="#9b947c"/><path d="M470 340L850 200 1170 340 880 520 490 440Z" fill="#e9ddbc"/><path d="M500 338L850 220 1140 340 880 492 510 430Z" fill="#c3d1ac"/><path d="M650 258V141l235-38 110 73v117l-245 46Z" fill="#e7e3ce"/><path d="M640 142l249-52 127 80-253 47Z" fill="#778e7c"/><path d="M650 258l100 71V217l-100-76Z" fill="#b8c5ad"/><g fill="#a9c7bf">${[0,1,2,3,4].map(i=>`<path d="M${780+i*40} ${214-i*7}v55l24-5v-55Z"/>`).join('')}</g><text x="870" y="154" text-anchor="middle" font-size="21" fill="#fff5d8">部本部 · BAPA海上會議廳</text><path d="M520 440l-130 22-60-42 132-27Z" fill="#b79c72"/>${flag('TW',540,230)}${flag('JP',625,200)}${flag('NL',1020,226)}${flag('IT',1105,266)}<ellipse cx="863" cy="424" rx="135" ry="60" fill="#997452"/><ellipse cx="863" cy="412" rx="135" ry="60" fill="#d6b788"/><ellipse cx="863" cy="410" rx="99" ry="39" fill="#e8d1a4"/><text x="863" y="415" text-anchor="middle" font-size="19" fill="#5d735f">證據 · 對等 · 合意</text></g><g id="bapa-ship" transform="translate(440 285)"><image href="assets/bapa-duck.png?v=same" x="-18" y="-52" width="156" height="136"/><g id="bapa-passengers"></g></g><g id="bapa-chairs" opacity="0">${[[756,407],[790,463],[858,490],[935,461],[980,400],[942,355],[864,344]].map(([x,y])=>`<g transform="translate(${x} ${y+15})"><path d="M-12-12v24M12-12v24" stroke="#736850" stroke-width="5"/><rect x="-16" y="-18" width="32" height="20" rx="6" fill="#668876"/><ellipse cy="2" rx="17" ry="8" fill="#8ca286"/></g>`).join('')}</g><g id="bapa-walkers">${D.delegates.map((p,i)=>`<g id="bapa-person-${i}">${person(p.name,p.color,i===0||i===2)}</g>`).join('')}${['高橋律','Sophie','Giulia'].map((n,i)=>`<g id="bapa-foreign-${i}" opacity="0">${person(n,['#8797bd','#c8a777','#ac8ba2'][i],i>0)}</g>`).join('')}</g></svg>`}
const phases=['boarding','depart','crossing','docking','seating','negotiation'],durations={boarding:18,depart:7,crossing:3,docking:8,seating:10},seats=[[756,407],[790,463],[858,490],[935,461]],boardingStarts=[[270,325],[340,334],[405,344],[315,374]],phaseNames={boarding:'國稅查核島・四位代表依序登船',depart:'全員到齊・小羊協商號向右出航',crossing:'穿越海霧・新的大海',docking:'部本部島・減速靠岸',seating:'步入圓桌・雙方準備就座',negotiation:'圓桌開場・把證據放到雙方中間'};
function startVoyage(){if(modal.open)return;modal.classList.remove('paper-open');phase='boarding';progress=0;elapsed=0;last=0;busy=false;modal.innerHTML=`<header class="bapa-nav"><div><small>THE BAPA VOYAGE · 原創小羊協商號</small><b>出發吧！征服BAPA</b></div><button class="choice" id="bapa-return">← 返回晶島群島</button></header><section class="bapa-stage"><div class="bapa-world">${svg()}</div><div class="bapa-stage-caption"><small>從查核走向雙邊協商</small><h2 id="bapa-scene-title">把案卷帶向另一片海。</h2><p id="bapa-scene-story">阿芬整理主張，小查抱著證據，王衡確認議程，阿卷收妥筆錄。等四人上船後，才一起出航。</p></div><div class="bapa-stage-control"><span id="bapa-phase-status" role="status"></span><button id="bapa-next-scene">快轉本段動畫 →</button></div></section><div id="bapa-theater" class="bapa-theater-wrap" hidden></div>`;modal.showModal();document.body.classList.add('bapa-voyage-open');$('#bapa-return').onclick=()=>modal.close();$('#bapa-next-scene').onclick=nextPhase;start=performance.now();drawFrame(0);raf=requestAnimationFrame(tick)}
function nextPhase(){if(phase==='negotiation'){openTheater();return}phase=phases[phases.indexOf(phase)+1];elapsed=0;last=0;drawFrame(0);if(phase==='negotiation')readySession()}
function readySession(){cancelAnimationFrame(raf);raf=0;$('#bapa-next-scene').textContent='進入圓桌劇場 →';$('#bapa-scene-title').textContent='我方理解了，但不認同。';$('#bapa-scene-story').textContent='四國旗迎風，今天每場只處理臺方與一個對造。對方說原文，我們看中譯；每一個爭點都要拿證據說話。'}
function useCase(id){selected=id;record=book[id]?.version===2?book[id]:L.fresh(id);return record}
function openTheater(){const box=$('#bapa-theater');modal.classList.add('bapa-theater-open');box.hidden=false;BAPATheater.mount(box,{peek:id=>book[id]?.version===2?book[id]:null,use:useCase,save:r=>{record=r;save()},reset:id=>{record=L.fresh(id);selected=id;save();return record},close:()=>modal.close(),voyage:()=>{modal.classList.remove('bapa-theater-open');box.hidden=true;box.innerHTML=''},amountHTML,prepareReports})}
function tick(t){if(!modal.open||document.hidden){raf=0;last=0;return}if(last&&t-last<48){raf=requestAnimationFrame(tick);return}const dt=last?Math.min((t-last)/1000,.2):0;last=t;if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)elapsed+=dt;progress=Math.min(1,elapsed/(durations[phase]||1));drawFrame(progress);if(progress>=1&&phase!=='negotiation')nextPhase();if(phase!=='negotiation')raf=requestAnimationFrame(tick)}
function drawFrame(p){if(!modal.open)return;const old=$('#bapa-old-port'),ministry=$('#bapa-ministry'),ship=$('#bapa-ship'),walkers=D.delegates.map((_,i)=>$('#bapa-person-'+i)),newSea=['docking','seating','negotiation'].includes(phase);old.setAttribute('opacity',newSea?'0':phase==='crossing'?String(1-p):'1');ministry.setAttribute('opacity',newSea?'1':phase==='crossing'?String(p):'0');let sx=500,sy=322,bob=Math.sin(elapsed*1.5)*3;
if(phase==='depart')sx=500+p*920;if(phase==='crossing')sx=1450;if(phase==='docking'){sx=-180+p*650;sy=390}if(phase==='seating'||phase==='negotiation'){sx=470;sy=390}ship.setAttribute('transform',`translate(${sx} ${sy+bob}) rotate(${Math.sin(elapsed)*1.2})`);
let aboard=0;for(let i=0;i<4;i++){const node=walkers[i];let x,y,show=true,moving=false;if(phase==='boarding'){const f=Math.max(0,Math.min(1,(p-i*.16)/.43));const [ax,ay]=boardingStarts[i];x=f<.65?ax+(505-ax)*(f/.65):505+(550-505)*((f-.65)/.35);y=f<.65?ay+(394-ay)*(f/.65):394+(351-394)*((f-.65)/.35);show=f<1;moving=f>0&&f<1;if(!show)aboard++;}else if(['depart','crossing','docking'].includes(phase)){show=false;aboard=4}else {const f=phase==='negotiation'?1:Math.max(0,Math.min(1,(p-i*.12)/.6));const way=f<.35?f/.35:1;x=f<.35?550+(656-550)*way:656+(seats[i][0]-656)*((f-.35)/.65);y=f<.35?455+(464-455)*way:464+(seats[i][1]-464)*((f-.35)/.65);moving=f>0&&f<1}node.setAttribute('opacity',show?'1':'0');if(show){node.setAttribute('transform',`translate(${x} ${y}) scale(.77)`);const gait=moving?Math.sin(elapsed*8+i)*13:0;const seated=phase==='negotiation'||phase==='seating'&&!moving;node.querySelector('.bapa-leg-left').setAttribute('transform',`rotate(${seated?-65:gait} -6 22)`);node.querySelector('.bapa-leg-right').setAttribute('transform',`rotate(${seated?-65:-gait} 6 22)`);}}
const passengers=$('#bapa-passengers');const displayCount=phase==='boarding'?aboard:['depart','crossing','docking'].includes(phase)?4:0;if(Number(passengers.dataset.count)!==displayCount){passengers.innerHTML=Array.from({length:displayCount},(_,i)=>`<g transform="translate(${i*20-8} 4) scale(.32)">${person('',D.delegates[i].color,i===0||i===2).replace('class="bapa-leg-left"','class="bapa-leg-left" transform="rotate(-72 -6 22)"').replace('class="bapa-leg-right"','class="bapa-leg-right" transform="rotate(72 6 22)"')}</g>`).join('');passengers.dataset.count=displayCount}
for(let i=0;i<3;i++){const n=$('#bapa-foreign-'+i);n.setAttribute('opacity',newSea?'1':'0');const f=phase==='seating'?p:phase==='negotiation'?1:0,positions=[[980,400],[942,355],[864,344]],x=900+i*38+(positions[i][0]-900-i*38)*f,y=290+i*18+(positions[i][1]-290-i*18)*f;n.setAttribute('transform',`translate(${x} ${y}) scale(.76)`)}$('#bapa-chairs').setAttribute('opacity',newSea?'1':'0');const headings={boarding:'把案卷帶向另一片海。',depart:'全員到齊，向右出航！',crossing:'海霧之後，是另一片大海。',docking:'部本部島，準備靠岸。',seating:'把證據，放到雙方中間。',negotiation:'我方理解了，但不認同。'};if($('#bapa-scene-title').textContent!==headings[phase])$('#bapa-scene-title').textContent=headings[phase];const status=phaseNames[phase]+(phase==='boarding'?' · 已登船 '+aboard+'／4':'');if($('#bapa-phase-status').textContent!==status)$('#bapa-phase-status').textContent=status;}
function greeting(){const c=L.get(record);return [{speaker:'阿芬｜臺方',text:'今天先談「'+c.theme+'」。臺方開場提案 '+pct(c.openingTW)+'（'+c.unit+'）。'},{speaker:c.delegate+'｜'+c.country+'代表',text:'我方先提出不同立場：'+pct(c.openingOther)+'。請注意這是立場，不是常規答案。'}]}
function amountHTML(a,c){if(!a)return '<p class="bapa-footnote">尚未提案，不預計算應同意的利潤率。</p>';return `<p>${esc(a.formula)}</p><div class="numbers"><div><small>臺灣本輪相關所得</small><b>${money(a.tw)}</b></div><div><small>${c.country}本輪相關所得</small><b>${money(a.other)}</b></div><div><small>臺灣相對已報差額</small><b>${a.delta>0?'+':''}${money(a.delta)}</b></div></div><p class="bapa-footnote">同範圍合計 ${money(a.pool)}。${a.valid?'雙邊橋接未重複計入同一利潤。':'本模型出現不合理負值，不能視為有效協議。'} ${c.id==='marketing'?'證據支持義方更多報酬時，臺灣差額可能為負；合理分配不是補稅競賽。':''}</p>`}
function prepareReports(){if(!window.TPReportExport)return;document.querySelectorAll('[data-bapa-export]').forEach(link=>download(link.dataset.bapaExport,link).catch(error=>{$('#bapa-result').textContent='文件產生失敗：'+error.message}))}
async function download(format,downloadLink){if(!window.TPReportExport){await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='report-formats.js';script.onload=resolve;script.onerror=reject;document.head.append(script)})}const c=L.get(record),a=L.amounts(record,record.proposal),blocks=[{type:'title',text:'BAPA出航篇｜協商教學紀錄'},{type:'subtitle',text:c.title+'・臺灣 × '+c.country},{type:'note',text:'本文件為虛構教學紀錄，非真實協議、核定、授權或簽署；不代表任何主管機關立場。'},{type:'heading',text:'一、本輪背景與範圍'},{type:'p',text:c.background},{type:'heading',text:'二、已閱讀文據與來源'}];for(const f of c.files)blocks.push({type:'p',text:(record.debate?'':record.read.includes(f[0])?'已閱 ':'未閱 ')+f.join('｜')});blocks.push({type:'heading',text:'三、雙方原始主張、反駁與追問'});for(const h of [...greeting(),...record.history])blocks.push({type:'p',text:h.speaker+'：'+h.text});blocks.push({type:'heading',text:'四、方法、提案及所得橋接'},{type:'p',text:'所選方法：'+(record.method||'未選')+'；本輪參考：'+c.method+'。理由：'+c.why},{type:'p',text:'提案：'+(record.proposal===''?'未填':pct(record.proposal))+'，指標：'+c.unit});if(a)blocks.push({type:'p',text:a.formula},{type:'table',headers:['臺灣所得','對造所得','臺灣較已報差額'],rows:[[money(a.tw),money(a.other),money(a.delta)]],widths:[1,1,1]});blocks.push({type:'heading',text:'五、結局、保留歧見與關鍵假設'},{type:'p',text:record.outcome?record.outcome.title+'：'+record.outcome.reason:'尚未提出結局；不能宣稱已合意。'},{type:'p',text:c.files[4][2]},{type:'p',text:'學習者筆記：'+(record.notes||'未填。')},{type:'p',text:record.debate?'圓桌攻防：論證可信度 '+record.debate.cred+'，會場緊張度 '+record.debate.tension+'，有力回應 '+record.debate.log.filter(x=>x.grade==='strong').length+' 次、失分 '+record.debate.log.filter(x=>x.grade==='weak').length+' 次。':'尚缺事項：'+(L.ready(record).join('；')||'本輪遊戲步驟已齊，真實案件證據充分性仍須另驗。')},{type:'heading',text:'六、依據與限制'},{type:'p',text:c.ref},{type:'p',text:'OECD TPG 2022 §4.134、§4.135、§4.173及Chapter IV Annex II。比率、估值與可靠範圍僅為本輪給定假設。所得橋接不等於核定稅額，不自動發生他方扣除或相對應調整。'});const blob=new Blob([TPReportExport[format]({blocks})],{type:format==='docx'?'application/vnd.openxmlformats-officedocument.wordprocessingml.document':'application/vnd.oasis.opendocument.text'}),url=URL.createObjectURL(blob),anchor=downloadLink;anchor.href=url;anchor.download='BAPA協商教學紀錄_'+c.id+'.'+format;reportUrls.push(url)}
modal.addEventListener('close',()=>{for(const url of reportUrls)URL.revokeObjectURL(url);reportUrls=[];cancelAnimationFrame(raf);raf=0;clearTimeout(replyTimer);busy=false;document.body.classList.remove('bapa-voyage-open');save();window.dispatchEvent(new Event('bapa-voyage-closed'));harbor.focus()});document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelAnimationFrame(raf);raf=0;last=0}else if(modal.open&&phase!=='negotiation'){last=0;raf=requestAnimationFrame(tick)}});harbor.onclick=startVoyage;
window.BAPAVoyage={open:startVoyage,anchor(project,scene){if(!harbor.isConnected)document.querySelector('.scene-viewport').append(harbor);const visible=scene.focus<0;harbor.hidden=!visible;if(!visible)return;const point=project([-2,.15,26]),W=scene.size[0],H=scene.size[1];harbor.hidden=point[0]<40||point[0]>W-40||point[1]<40||point[1]>H-16;if(!harbor.hidden){harbor.style.left=Math.round(point[0])+'px';harbor.style.top=Math.round(point[1])+'px';harbor.style.width='52px'}},isOpen:()=>modal.open};
