const dock=document.createElement('button');dock.className='mist-entry';dock.id='bapa-dock-entry';dock.innerHTML='<span>⛵</span><div><b>小羊協商號・BAPA出航篇</b><small>登船 → 新海域 → 部本部島 → 雙邊圓桌攻防</small></div><em>出發吧！征服BAPA ↗</em>';dock.onclick=()=>{TPScene?.focus(6);startVoyage()};document.querySelector('.explorer').insertAdjacentElement('afterend',dock);
